  server.registerTool("import_monophonic_score", {
    title: "Import Local Monophonic Score",
    description: "Convert one inspected, rights-cleared local MusicXML or SMF MIDI lane into Group-local SynthV notes and apply it through the ordinary guarded add_notes path in exactly one undo record. The SHA-256 guard must still match; ambiguous selection, overlap/polyphony, unsafe XML, more than 512 notes, URLs, and .svp files are rejected before any project write. Source tempo is reported but never silently applied to the project.",
    inputSchema: {
      ...groupLocatorShape,
      ...localScoreReadShape,
      ...localScoreSelectionShape,
      ...localScoreConversionShape,
      expectedFileFingerprint: string2().regex(/^sha256:[0-9a-f]{64}$/u).describe("Fresh fileFingerprint returned by inspect_score_file."),
      rightsConfirmed: literal(true).describe("Confirm that the user is authorized to import this local score."),
      grouping: _enum2(["target", "ensureNonMain"]).default("ensureNonMain").describe("ensureNonMain safely creates an editable non-main Group when the target is the track main Group."),
      groupName: string2().min(1).max(200).optional(),
      sharedGroupPolicy: _enum2(["reject", "allowAllReferences"]).default("reject"),
      expectedReferenceCount: number2().int().min(1).optional(),
      previewNoteLimit: number2().int().min(1).max(512).default(64)
    },
    annotations: {
      readOnlyHint: false,
      destructiveHint: false,
      idempotentHint: false,
      openWorldHint: false
    }
  }, async (input) => runTool(async () => {
    try {
      const snapshot = await readLocalScoreSnapshot(input.filePath, {
        maxFileBytes: input.maxFileBytes
      });
      const inspection = inspectScoreSnapshot(snapshot, {
        onsetBlickOffset: input.onsetBlickOffset
      });
      const selection = scoreSelection(inspection, input, true);
      const imported = importScoreSnapshotMonophonic(snapshot, selection, input.expectedFileFingerprint, {
        onsetBlickOffset: input.onsetBlickOffset,
        transposeSemitones: input.transposeSemitones,
        defaultLyric: input.defaultLyric
      });
      if (imported.notes.length > MAX_IMPORTED_SCORE_NOTES2) {
        throw new BridgeError(`The selected score lane contains ${imported.notes.length} notes; SynthV imports are limited to ${MAX_IMPORTED_SCORE_NOTES2} notes per undo record.`, "SCORE_NOTE_LIMIT_EXCEEDED", {
          noteCount: imported.notes.length,
          maximum: MAX_IMPORTED_SCORE_NOTES2,
          requiredAction: "Select a smaller source lane or split the legal source file before importing."
        });
      }
      const hostResult = await client.send("add_notes", {
        trackIndex: input.trackIndex,
        groupIndex: input.groupIndex,
        ...input.groupUuid === void 0 ? {} : { groupUuid: input.groupUuid },
        notes: imported.notes,
        grouping: input.grouping,
        ...input.groupName === void 0 ? {} : { groupName: input.groupName },
        sharedGroupPolicy: input.sharedGroupPolicy,
        ...input.expectedReferenceCount === void 0 ? {} : {
          expectedReferenceCount: input.expectedReferenceCount
        }
      });
      const hostRecord = typeof hostResult === "object" && hostResult !== null && !Array.isArray(hostResult) ? hostResult : { hostResult };
      return {
        ...hostRecord,
        sourceScore: compactScoreImport(imported, input.previewNoteLimit),
        sourceTempoAppliedToProject: false,
        undoRecordCount: 1
      };
    } catch (error51) {
      throw asScoreBridgeError(error51);
    }
  }));
